# Расчет функции y = 24x + 3

def calculate_y(x):
    return 24 * x + 3

# Пример использования
try:
    x_value = float(input('Введите значение x: '))
    result = calculate_y(x_value)
    print(f'Для x = {x_value}, y = {result}')
except ValueError:
    print('Пожалуйста, введите числовое значение.')

